<?php
use App\Models\{CaseStudy,User,WebsiteSetting}; use Illuminate\Foundation\Testing\RefreshDatabase; uses(RefreshDatabase::class); beforeEach(function(){file_put_contents(storage_path('app/installed'),now()->toIso8601String());WebsiteSetting::create(['site_name'=>'Test','site_url'=>'https://example.test','timezone'=>'UTC']);}); afterEach(fn()=>@unlink(storage_path('app/installed'))); test('case study lifecycle protects private content',function(){CaseStudy::factory()->create(['slug'=>'private']);CaseStudy::factory()->published()->create(['slug'=>'verified-story','title'=>'Verified story']);$this->get('/case-studies')->assertSuccessful()->assertSee('Verified story');$this->get('/case-studies/private')->assertNotFound();$this->get('/case-studies/verified-story')->assertSuccessful();}); test('case study requires truthful narrative fields',function(){$user=User::factory()->create(['is_active'=>true]);$this->actingAs($user)->post('/content/case-studies',['title'=>'Incomplete','slug'=>'incomplete'])->assertSessionHasErrors(['short_description','challenge','solution','outcome']);});
